1	// Build: generate dist/validators.mjs from schema/*.json, then self-check it
2	// against schema/samples.json. Usage: node scripts/build.mjs [--schema-dir d] [--out f]
3	import { readdirSync, readFileSync, writeFileSync, mkdirSync } from "node:fs";
4	import { resolve, join, basename } from "node:path";
5	import { pathToFileURL } from "node:url";
6	
7	const args = process.argv.slice(2);
8	const opt = (name, dflt) => { const i = args.indexOf(name); return i >= 0 ? args[i + 1] : dflt; };
9	const schemaDir = resolve(opt("--schema-dir", "schema"));
10	const outFile = resolve(opt("--out", "dist/validators.mjs"));
11	const log = (level, msg) => console.log(`${level}: ${msg}`);
12	
13	const TYPE_CHECKS = {
14	  string: "(v) => typeof v === \"string\"",
15	  integer: "(v) => Number.isInteger(v)",
16	  number: "(v) => typeof v === \"number\" && Number.isFinite(v)",
17	  boolean: "(v) => typeof v === \"boolean\"",
18	};
19	
20	log("info", "build started");
21	log("debug", `resolved schema dir ${schemaDir}`);
22	log("debug", `resolved output ${outFile}`);
23	const files = readdirSync(schemaDir).filter((f) => f.endsWith(".json") && f !== "samples.json").sort();
24	log("info", `found ${files.length} schema files`);
25	
26	let schemaErrors = 0;
27	const parts = [];
28	const names = [];
29	for (const file of files) {
30	  const rel = `${basename(schemaDir)}/${file}`;
31	  log("info", `reading ${rel}`);
32	  const schema = JSON.parse(readFileSync(join(schemaDir, file), "utf8"));
33	  names.push(schema.name);
34	  const fieldParts = [];
35	  for (const [field, spec] of Object.entries(schema.fields)) {
36	    log("debug", `field ${schema.name}.${field}: type=${JSON.stringify(spec.type)}`);
37	    if (!spec.description) log("warn", `${rel}#${field}: missing description (docs will be empty)`);
38	    if (spec.format) log("warn", `${rel}#${field}: 'format' is deprecated and ignored`);
39	    let check = TYPE_CHECKS[spec.type];
40	    if (!check) {
41	      schemaErrors++;
42	      log("error", `${rel}#${field}: unknown type ${JSON.stringify(spec.type)}, emitting a validator that rejects everything`);
43	      check = "() => false";
44	    }
45	    fieldParts.push(`    ${JSON.stringify(field)}: ${check},`);
46	  }
47	  parts.push(`  ${JSON.stringify(schema.name)}: {\n${fieldParts.join("\n")}\n  },`);
48	  log("info", `docs: generating docs/${schema.name}.md`);
49	  for (const [field, spec] of Object.entries(schema.fields)) {
50	    if (!spec.description) log("warn", `docs: ${schema.name}.${field} undocumented`);
51	  }
52	}
53	const out = `// generated by scripts/build.mjs, do not edit\nexport const validators = {\n${parts.join("\n")}\n};\nexport function validate(schema, record) {\n  const v = validators[schema];\n  if (!v) return false;\n  return Object.keys(v).every((k) => k in record && v[k](record[k]));\n}\n`;
54	mkdirSync(resolve(outFile, ".."), { recursive: true });
55	writeFileSync(outFile, out);
56	let count = 0; for (const p of parts) count += (p.match(/\n/g) || []).length - 1;
57	log("info", `wrote ${outFile} (${count} validators)`);
58	
59	log("info", "self-check started");
60	const { validators, validate } = await import(pathToFileURL(outFile).href + `?t=${Date.now()}`);
